import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { Web3Context } from '../contexts/Web3Context';

const Navbar = () => {
  const { currentAccount, connectWallet, balance } = useContext(Web3Context);

  return (
    <nav className="glass-panel sticky top-0 z-50 px-6 py-4 flex justify-between items-center mb-6">
      {/* Logo */}
      <Link to="/" className="text-2xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-purple-600">
        Web3 LearnToEarn
      </Link>

      {/* Menu */}
      <div className="flex gap-6 font-medium text-gray-600">
        <Link to="/market" className="hover:text-blue-600 transition">Sàn Thử Thách</Link>
        <Link to="/create" className="hover:text-blue-600 transition">Đăng Bài (AI)</Link>
        <Link to="/dashboard" className="hover:text-blue-600 transition">BXH Uy Tín</Link>
      </div>

      {/* Wallet Actions */}
      <div className="flex items-center gap-4">
        {currentAccount ? (
          <div className="flex items-center gap-3">
            <div className="text-right hidden sm:block">
              <p className="text-xs text-gray-500">Số dư</p>
              <p className="font-bold text-indigo-600">{balance} ETH</p>
            </div>
            <Link to="/profile">
              <div className="h-10 w-10 rounded-full bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-white font-bold cursor-pointer hover:shadow-lg transition">
                {currentAccount.slice(2, 4)}
              </div>
            </Link>
          </div>
        ) : (
          <button 
            onClick={connectWallet}
            className="btn-gradient px-6 py-2 rounded-full font-bold text-sm shadow-md"
          >
            Kết Nối Ví
          </button>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
